cd isQ-Compiler
# Enter development shell and run the rest inside it
nix develop --command bash -c '
 # Step 4: Create a minimal isQ source with a 2-bit AND oracle
 cat > test.isq << EOF
// AND oracle: |x, y, 0> -> |x, y, x AND y>
// We use a Toffoli (ccx) gate.

oracle ccx q[0], q[1], q[2];

module main() {
 qubit[3] q;
 // Initialize input: x = |1>, y = |1> (so AND = 1)
 x q[0];
 x q[1];
 // Apply Toffoli
 ccx q[0], q[1], q[2];
 // q[2] now holds the AND result
 measure q[2];
}
EOF
 # Step 5: Compile using isQ compiler
 # (assuming the isqc command is available inside the dev shell)
 isqc compile test.isq -o output.qasm 2>&1
 # Verify the output file exists and is non-empty
 if [ -f output.qasm ] && [ -s output.qasm ]; then
 echo "Compilation successful. Output file: output.qasm"
 head -10 output.qasm
 else
